-- Mise à jour de la table doctors
UPDATE doctors d
SET
  commune       = i.commune,
  opening_hours = i.opening_hours,
  updated_at    = now()
FROM _doctors_import i
WHERE d.id = i.id
  AND (i.commune IS NOT NULL OR i.opening_hours IS NOT NULL);

-- Nettoyage
DROP TABLE _doctors_import;

-- Vérification
SELECT COUNT(*) AS medecins_avec_commune  FROM doctors WHERE commune IS NOT NULL;
SELECT COUNT(*) AS medecins_avec_horaires FROM doctors WHERE opening_hours IS NOT NULL;
SELECT id, name_fr, commune, LEFT(opening_hours, 60) AS horaires_apercu
FROM doctors
WHERE commune IS NOT NULL
LIMIT 5;
